USE db_keperawatan;

INSERT INTO bank_soal (jenis_tes, topik, judul, deskripsi, pertanyaan)
VALUES ('PK1', 'Infeksi Nosokomial', 'Asesmen PK 1 Infeksi Nosokomial', 'Asesmen unit kompetensi KES.VK001.003.01 Menerapkan Prinsip Infeksi Nosokomial.', CONVERT( USING utf8mb4))
ON DUPLICATE KEY UPDATE judul=VALUES(judul), deskripsi=VALUES(deskripsi), pertanyaan=VALUES(pertanyaan);

