SET f.judul='Asesmen PK 1 Infeksi Nosokomial', f.deskripsi='Asesmen unit kompetensi KES.VK001.003.01 Menerapkan Prinsip Infeksi Nosokomial.', f.pertanyaan=CONVERT( USING utf8mb4)
WHERE p.jenis_tes='PK1' AND p.topik='Infeksi Nosokomial';
